-- The schema and rows of a desk from before the cue model plan's session 1: `cues` still carries
-- the stack, sort order, number, follow and type, and `prompt_book_anchors` names a cue.
-- `CueModelMigrationTest` loads it into a fresh file and runs `CueModelMigration` over it.
--
-- Generated once from `seedRichProject` on the commit before the change (3a58d38) by dumping
-- `sqlite_master` and every row, then extended by hand at the end with the edge cases the fixture
-- does not reach. Never regenerate it from a later commit: it is the old shape, frozen.
-- Statements are separated by ";\n" and nothing inside a value contains that sequence.
CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, "name" VARCHAR(50) NOT NULL, description VARCHAR(255) NULL, is_current BOOLEAN DEFAULT 0 NOT NULL, active_stack_id INT NULL, stage_width_m DOUBLE PRECISION NULL, stage_depth_m DOUBLE PRECISION NULL, stage_height_m DOUBLE PRECISION NULL, uuid BINARY(16) NOT NULL, kind VARCHAR(16) DEFAULT 'SHOW' NOT NULL, venue_uuid BINARY(16) NULL, venue_version INT NULL, venue_repo VARCHAR(300) NULL, CONSTRAINT chk_projects_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_projects_signed_integer_active_stack_id CHECK (active_stack_id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_projects_signed_integer_venue_version CHECK (venue_version BETWEEN -2147483648 AND 2147483647));
INSERT INTO "projects" ("id", "name", "description", "is_current", "active_stack_id", "stage_width_m", "stage_depth_m", "stage_height_m", "uuid", "kind", "venue_uuid", "venue_version", "venue_repo") VALUES (1, 'round-trip-rich', 'exercises every synced table', 1, 1, 12.0, 8.0, 6.0, X'071cd92935c7491bb5ee9052bf6809b4', 'SHOW', NULL, NULL, NULL);
